import { cn } from '@/lib/utils'

/** Join QR code from `joinQrSvg()` on a white card, scaled to the container; callers set width and rounding. */
export function JoinQr({ svg, url, className }: { svg: string; url: string; className?: string }) {
  return (
    <div
      role="img"
      aria-label={`QR-Code für ${url}`}
      className={cn('rounded-2xl bg-white p-4 [&>svg]:h-auto [&>svg]:w-full', className)}
      // Path data generated by our own QR library from our own URL
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  )
}
